import{_ as r,l as i,o as a,c as l,v as o,p as s,x as t,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const X=JSON.parse('{"title":"Open X-Embodiment","description":"","frontmatter":{"title":"Open X-Embodiment","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/open-x-embodiment.md","filePath":"llm/open-x-embodiment.md","lastUpdated":1789023840000}'),E={name:"llm/open-x-embodiment.md"};function g(h,e,b,T,R,c){const n=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="open-x-embodiment" tabindex="-1">Open X-Embodiment <a class="header-anchor" href="#open-x-embodiment" aria-label="Permalink to &quot;Open X-Embodiment&quot;">​</a></h1><div class="epigraph"><p>我们能否训练「跨机器人」的通才策略，并高效适配到新的机器人、任务与环境？</p><footer>—— Open X-Embodiment Collaboration, Open X-Embodiment: Robotic Learning Datasets and RT-X Models, arXiv:2310.08864</footer></div><p>2023 年 10 月，Google DeepMind 与合作实验室发布 <strong>Open X-Embodiment（OXE）</strong> 数据集与 <strong>RT-X</strong> 模型。DeepMind 博客 <em>Scaling up learning across many different robot types</em>（Vuong &amp; Sanketi，2023-10-03）把故事写成：机器人一直是专家、不是通才；换机、换任务、换房间往往要从头训。OXE 把许多实验室已经采过的轨迹收成统一格式，检验一件事——<strong>正迁移</strong>：在多本体上共训，是否比只在本机数据上训更好。论文 arXiv:2310.08864，ICRA 2024。arXiv 第一版通讯作者序列以 <strong>Abhishek Padalkar</strong> 等领衔；后续版本改为字母序，署名 Open X-Embodiment Collaboration（Abby O&#39;Neill 等）。引用时两者指向同一工作。项目页 robotics-transformer-x.github.io，代码在 <code>google-deepmind/open_x_embodiment</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视觉有 ImageNet，语言有网页语料，机器人交互日志既小又窄：同一房间、同一套物体、同一控制频率。再大的单一实验室数据集，也只是「一个岛」。先前跨本体工作往往要设计共享动作空间、域翻译或显式对齐；OXE 的实验立场相反：用最小对齐、高容量 Transformer，看正迁移是否已经出现。</p><p>第二个目标是基础设施。没有统一格式，21 个机构的 60 个数据集无法进同一个加载器。OXE 选择 RLDS / TFRecord，允许不同相机数、深度、点云与动作维，并提供并行加载。数据集本身不是新算法；算法贡献是证明 RT-1 与 RT-2 在几乎不改结构的情况下就能吃下混合物。</p><h3 id="_22-个本体不是-22-个可互换的人" tabindex="-1">22 个本体不是 22 个可互换的人 <a class="header-anchor" href="#_22-个本体不是-22-个可互换的人" aria-label="Permalink to &quot;22 个本体不是 22 个可互换的人&quot;">​</a></h3><p>论文与项目页：超过 100 万条真机轨迹，<strong>22</strong> 种本体（单臂、双臂、四足等），合作叙述从 21 个机构扩展到博客中的 33 个实验室；<strong>527</strong> 种技能、<strong>160266</strong> 个任务。Franka 场景最多样；xArm 与 Google Robot 贡献大量轨迹。语言指令用 PaLM 抽物体与技能后，主体仍是 pick-place 家族，长尾才是擦拭、装配。动作在训练时被粗对齐成相对夹爪坐标系的 7 维（平移、旋转、夹爪），观测取一个规范相机、统一分辨率。坐标系、绝对/相对/速度、相机外参<strong>不</strong>做精细对齐——同一数字在不同机上是不同运动。</p><p><span class="marginnote">博客写 22 种机器人、500+ 技能、15 万+ 任务、100 万+ episode，与论文摘要的 527 / 160266 一致到数量级。实验用的共训混合物只有 <strong>9</strong> 个操作本体：当时完整仓库还在涨。后来 π₀、GR00T 把 OXE 当开源底座，用的是仓库而非 2023 年那 9 机混合物。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>RT-1-X</strong>：35M 级、专为机器人设计的 Transformer。15 帧历史图像经 ImageNet 预训练 EfficientNet，语言经 USE 嵌入，FiLM 融合后约 81 个视觉—语言 token，解码器输出离散动作桶。只在机器人混合物上训。<strong>RT-2-X</strong>：把离散动作写成数字文本，与网页视觉语言数据大约 1:1 共微调，骨干是 RT-2 的 PaLI-X（ViT + UL2，WebLI）。动作每维 256 桶，外加终止维。损失都是词表上的交叉熵。推理 3–10 Hz；RT-1 本地，RT-2 当时走云端查询。</p><p>评测分两条。分布内技能：在合作实验室用各家「原方法」与只在本机上训的 RT-1 对照。博客与论文：RT-1-X 平均成功率约 <strong>+50%</strong>。涌现技能：在 Google 机器人上测 RT-2 训练域里没有、但其他本体数据里有的空间关系与介词（apple <em>on</em> cloth 对 <em>near</em> cloth）。RT-2-X 相对 RT-2 约 <strong>3×</strong>。容量表：在 Bridge、RT-1 原论文数据这种大岛上，35M 的 RT-1-X 会欠拟合、低于本机 RT-1；55B 的 RT-2-X 才能在大数据域上持平或超过——通才不是无条件的，要够宽。</p><h3 id="格式统一是方法-不是预处理脚注" tabindex="-1">格式统一是方法，不是预处理脚注 <a class="header-anchor" href="#格式统一是方法-不是预处理脚注" aria-label="Permalink to &quot;格式统一是方法，不是预处理脚注&quot;">​</a></h3><p>没有 RLDS，就无法在同一批里混 WidowX 与 Google Robot。粗对齐 7 维末端，是故意把「embodiment gap」留给网络，而不是先做运动学重定向。这解释了后续 VLA 为何仍要零填充更高维关节：OXE 证明正迁移在末端空间成立，不证明任意人形全身动作可以同一套 7 维桶。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正迁移的机制假设是：抓、放、推在视觉—语言上共享统计，本体差异可被当作输入条件（通过不同视觉外观与未对齐的动作尺度）吸收。小模型在大岛上变差，说明混合物增加的是需要容量去记忆的多峰分布，而不是免费的正则。RT-2-X 的 3× 涌现被解释为：其他机器人的轨迹提供了原 RT-2 数据里缺失的空间介词与物体组合，高容量 VLM 才能把网页语义接到这些新动作上。介词实验是机制证据：只改 <em>on</em> / <em>near</em>，轨迹形状改变，说明语言条件真正调制了低层行为，而不是忽略指令、重复示范均值。</p><p>开放仓库的机制是社会性的：单个实验室采不到互联网级交互，但可以约定格式。ImageNet 类比是 DeepMind 博客原句，指的是评测与预训练习惯的转移，不是 OXE 已经达到 ImageNet 的清洗程度。</p><p><span class="marginnote">「Original Method」指各数据集作者为自己数据调过的模型，是强基线而不是弱随机策略。+50% 是多实验室、多机平均，单机可能更小或更大。RT-2-X 55B 权重并未像 RT-1-X 那样完整开源推理包；开放的是数据集、部分检查点与 RT-1-X。</span></p><h3 id="跨本体并不消除控制频率与安全栈" tabindex="-1">跨本体并不消除控制频率与安全栈 <a class="header-anchor" href="#跨本体并不消除控制频率与安全栈" aria-label="Permalink to &quot;跨本体并不消除控制频率与安全栈&quot;">​</a></h3><p>3–10 Hz 的离散末端增量适合当时的移动操作演示，不适合 50 Hz 灵巧手。π₀ 后来用流匹配动作块，正是因为 OXE 式 tokenization 在高频上不够。OXE 也几乎不谈力控、接触安全与人机共享空间；它提供的是学习起点，不是控制器。</p>',20)),(a(),s(m,null,{default:t(()=>[d(n,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20LABS%5B%2221%2B%20%E6%9C%BA%E6%9E%84%2060%20%E4%B8%AA%E6%95%B0%E6%8D%AE%E9%9B%86%22%5D%20--%3E%20RLDS%5B%22RLDS%20%E7%BB%9F%E4%B8%80%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20RLDS%20--%3E%20MIX%5B%229%20%E6%9C%BA%E5%AE%9E%E9%AA%8C%E6%B7%B7%E5%90%88%E7%89%A9%20%2F%2022%20%E6%9C%BA%E4%BB%93%E5%BA%93%22%5D%0A%20%20MIX%20--%3E%20RT1%5B%22RT-1-X%2035M%20%E4%BB%85%E6%9C%BA%E5%99%A8%E4%BA%BA%22%5D%0A%20%20MIX%20--%3E%20RT2%5B%22RT-2-X%20VLM%20%E5%85%B1%E5%BE%AE%E8%B0%83%22%5D%0A%20%20WEB%5B%22%E7%BD%91%E9%A1%B5%E8%A7%86%E8%A7%89%E8%AF%AD%E8%A8%80%22%5D%20--%3E%20RT2%0A%20%20RT1%20--%3E%20POS%5B%22%E5%88%86%E5%B8%83%E5%86%85%20%2B50%25%20%E5%B9%B3%E5%9D%87%22%5D%0A%20%20RT2%20--%3E%20EMG%5B%22%E6%B6%8C%E7%8E%B0%E6%8A%80%E8%83%BD%E7%BA%A6%203%C3%97%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>技能长尾薄，多数仍是桌面操作。粗对齐会把「看起来可迁移」的失败藏进动作尺度：同一输出在另一机上可能过冲。评测由各实验室执行，场景与评分不完全同一协议。数据集持续追加，论文数字是快照；引用时写 arXiv:2310.08864 与项目页当时的统计。RT-2-X 的云端推理延迟与隐私不在开放复现范围内。</p><p>不要把 OXE 写成已经训出可商用的通用机器人。它证明正迁移存在，并提供至今仍被 π₀、OpenVLA、GR00T 引用的底座。也不要把 Padalkar et al. 与 O&#39;Neill et al. 当成两篇论文——是同一合作的署名演变。后续 Open X 的扩充集、DROID 单独论文，应分开引用。</p><p><span class="marginnote">出处：Open X-Embodiment Collaboration，<em>Open X-Embodiment: Robotic Learning Datasets and RT-X Models</em>，arXiv:2310.08864，ICRA 2024，DOI 10.1109/ICRA57147.2024.10611477；DeepMind 博客 <a href="https://deepmind.google/blog/scaling-up-learning-across-many-different-robot-types/" target="_blank" rel="noreferrer">https://deepmind.google/blog/scaling-up-learning-across-many-different-robot-types/</a> ；项目 <a href="https://robotics-transformer-x.github.io/" target="_blank" rel="noreferrer">https://robotics-transformer-x.github.io/</a> 。RT-1、RT-2 为 Brohan 等先前工作。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OXE 把 22 个本体、100 万+ 轨迹收成统一 RLDS 仓库，用于跨机器人学习。</li><li>RT-1-X 在合作实验室平均约 +50% 相对本机方法；RT-2-X 在涌现技能上约 3× 于 RT-2。</li><li>动作粗对齐为 7 维末端；不精细对齐坐标系，把本体差留给网络。</li><li>小模型在大数据岛上会欠拟合，正迁移需要容量。</li><li>开放的是数据与部分检查点；实验混合物小于后来的完整仓库。</li><li>出处：arXiv:2310.08864、ICRA 2024 与 DeepMind 2023-10-03 博客；早期版本常引 Padalkar et al.。</li></ul>',6))])}const A=r(E,[["render",g]]);export{X as __pageData,A as default};
